#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

vector<int> res;

void solve(int n, int k) {
    if (n == 1) {
        return;
    }
    if (k == 1) {
        res.push_back(n);
        return;
    }
    for (int i = 2; i <= (int)sqrt(n) + 1; i++) {
        if (n % i == 0) {
            res.push_back(i);
            solve(n / i, k - 1);
            return;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    cin >> n >> k;

    solve(n, k);

    if (res.empty() || res.size() != k) {
        cout << -1 << endl;
        return 0;
    }

    long long check = 1;
    for (int el : res) {
        check *= el;
    }
    if (check != n) {
        cout << -1 << endl;
        return 0;
    }

    for (size_t i = 0; i < res.size(); i++) {
        if (i == res.size() - 1) {
            cout << res[i] << "\n";
        } else {
            cout << res[i] << " ";
        }
    }

    return 0;
}

